```python
import re


def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    def parse_version(s):
        if "+" in s:
            raise ValueError("build metadata not allowed")

        m = re.fullmatch(
            r"(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
            r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?",
            s
        )
        if not m:
            raise ValueError("invalid version")

        major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
        pre_str = m.group(4)

        if pre_str is None:
            return (major, minor, patch, None)

        identifiers = pre_str.split(".")
        for ident in identifiers:
            if ident == "":
                raise ValueError("invalid prerelease identifier")
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == "0":
                    raise ValueError("invalid numeric prerelease identifier")

        return (major, minor, patch, tuple(identifiers))

    def compare_versions(a, b):
        for i in range(3):
            if a[i] != b[i]:
                return -1 if a[i] < b[i] else 1

        a_pre, b_pre = a[3], b[3]
        if a_pre is None and b_pre is None:
            return 0
        if a_pre is None:
            return 1
        if b_pre is None:
            return -1

        for x, y in zip(a_pre, b_pre):
            x_num = x.isdigit()
            y_num = y.isdigit()

            if x_num and y_num:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif x_num:
                return -1
            elif y_num:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1

        if len(a_pre) != len(b_pre):
            return -1 if len(a_pre) < len(b_pre) else 1

        return 0

    def parse_comparator(token):
        m = re.fullmatch(
            r"(>=|<=|>|<|=|\^|~)?"
            r"((?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)"
            r"(?:-[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?)",
            token
        )
        if not m:
            raise ValueError("invalid comparator")

        op = m.group(1) or ""
        ver = parse_version(m.group(2))
        return op, ver

    def parse_range(r):
        sets = []
        for part in r.split("||"):
            comparators = part.split()
            if not comparators:
                raise ValueError("empty comparator set")
            sets.append([parse_comparator(c) for c in comparators])
        return sets

    def satisfies_set(ver, comparators):
        if ver[3] is not None:
            prerelease_match = False
            for _, named in comparators:
                if named[3] is not None and named[:3] == ver[:3]:
                    prerelease_match = True
                    break
            if not prerelease_match:
                return False

        for op, named in comparators:
            cmp = compare_versions(ver, named)

            if op == "":
                if cmp != 0:
                    return False
            elif op == "=":
                if cmp != 0:
                    return False
            elif op == ">":
                if cmp <= 0:
                    return False
            elif op == ">=":
                if cmp < 0:
                    return False
            elif op == "<":
                if cmp >= 0:
                    return False
            elif op == "<=":
                if cmp > 0:
                    return False
            elif op == "^":
                if cmp < 0:
                    return False

                major, minor, patch = named[:3]
                if major > 0:
                    upper = (major + 1, 0, 0, None)
                elif minor > 0:
                    upper = (0, minor + 1, 0, None)
                else:
                    upper = (0, 0, patch + 1, None)

                if compare_versions(ver, upper) >= 0:
                    return False
            elif op == "~":
                if cmp < 0:
                    return False

                major, minor, patch = named[:3]
                upper = (major, minor + 1, 0, None)
                if compare_versions(ver, upper) >= 0:
                    return False

        return True

    parsed_version = parse_version(version)
    parsed_range = parse_range(rng)

    return any(satisfies_set(parsed_version, comparators) for comparators in parsed_range)
